const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Elephant Butte Reservoir location
  const reservoir = ee.Geometry.Point([-107.19, 33.15]).buffer(5000);

  // 2. Date definitions
  const date1986 = '1986-06-12';
  const date2020 = '2020-06-09';

  // 3. Landsat 5 for 1986
  let col1986 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(reservoir)
    .filterDate(date1986, ee.Date(date1986).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size1986 = col1986.size().getInfo();
  console.log(`1986 Images found: ${size1986}`);

  if (size1986 === 0) {
    // Try wider date range
    col1986 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(reservoir)
      .filterDate('1986-06-01', '1986-06-30')
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    const size1986_wide = col1986.size().getInfo();
    console.log(`1986 Images (wider range): ${size1986_wide}`);

    if (size1986_wide === 0) {
      console.log('No data for 1986');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Landsat 8 for 2020
  let col2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(reservoir)
    .filterDate(date2020, ee.Date(date2020).advance(1, 'day'))
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size2020 = col2020.size().getInfo();
  console.log(`2020 Images found: ${size2020}`);

  if (size2020 === 0) {
    // Try wider date range
    col2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(reservoir)
      .filterDate('2020-06-01', '2020-06-30')
      .filter(ee.Filter.lt('CLOUD_COVER', 30));

    const size2020_wide = col2020.size().getInfo();
    console.log(`2020 Images (wider range): ${size2020_wide}`);

    if (size2020_wide === 0) {
      console.log('No data for 2020');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 5. Process 1986 image
  const img1986 = col1986.first();
  const green1986 = img1986.select('SR_B2').multiply(0.0000275).add(-0.2);
  const nir1986 = img1986.select('SR_B4').multiply(0.0000275).add(-0.2);
  const ndwi1986 = green1986.subtract(nir1986).divide(green1986.add(nir1986));
  const water1986 = ndwi1986.gt(0);

  // 6. Process 2020 image
  const img2020 = col2020.first();
  const green2020 = img2020.select('SR_B3').multiply(0.0000275).add(-0.2);
  const nir2020 = img2020.select('SR_B5').multiply(0.0000275).add(-0.2);
  const ndwi2020 = green2020.subtract(nir2020).divide(green2020.add(nir2020));
  const water2020 = ndwi2020.gt(0);

  // 7. Calculate water extent (pixel counts)
  const stats1986 = water1986.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: reservoir,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2020 = water2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: reservoir,
    scale: 3000,
    maxPixels: 1e9
  });

  const waterPixels1986 = stats1986.get('SR_B2').getInfo();
  const waterPixels2020 = stats2020.get('SR_B3').getInfo();

  console.log(`1986 Water pixels: ${waterPixels1986}`);
  console.log(`2020 Water pixels: ${waterPixels2020}`);

  // 8. Validation and answer
  if (waterPixels1986 === null || waterPixels2020 === null) {
    console.log('Calculation failed');
    console.log('<answer>C3</answer>');
    return;
  }

  if (waterPixels1986 === 0 && waterPixels2020 === 0) {
    console.log('No valid water pixels detected');
    console.log('<answer>C2</answer>');
    return;
  }

  if (waterPixels2020 < waterPixels1986) {
    console.log('Water extent decreased');
    console.log('<answer>A</answer>');
  } else {
    console.log('Water extent did not decrease');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
